from lib import *
S = SS('w37')
steps = [
    step("一次真实的 HTTP 请求(en0,example.com:80)的头几个包,序号用相对值(减去各自的初始序号):① 客户端 SYN:相对序号 0,头长 44 字节,标志 CWR+ECE+SYN,窗口 65535;② 服务器 SYN-ACK:相对序号 0、相对确认号 1(确认客户端的 SYN 占了 1 个序号),头长 40,标志 ECE+ACK+SYN,窗口 65535;③ 客户端 ACK:头长 32,窗口字段 2061;④ 客户端 ACK+PSH 带 56 字节的请求;⑤ 服务器 ACK:确认号 57(= 1 + 56),窗口 16;⑥ 服务器 ACK+PSH 带 923 字节,⑦ 再带 5 字节(相对序号 924),⑧ 客户端 ACK 确认号 929(= 1 + 923 + 5);⑨ 服务器 ACK+FIN 在相对序号 929。整个连接共 12 个包。TCP 头固定 20 字节:源端口 2、目的端口 2、序号 4、确认号 4、数据偏移 4 位加保留 4 位、标志 1 字节(CWR ECE URG ACK PSH RST SYN FIN)、窗口 2、校验和 2、紧急指针 2,之后是选项。第 1 个包的头 20 字节是 c080 0050 7432 eaec 0000 0000 b0c2 ffff 3e01 0000:数据偏移 11(× 4 = 44 字节),标志字节 0xc2。", t=tl(S(1)), mark=lidx(S(1), 'CWR+ECE+SYN', 'ECE+ACK+SYN', 'ACK+PSH'), done=lidx(S(1), '整个连接共', '第 1 个包(SYN)的头', '#  方向'), b=bars([['SYN 的头', 44, '44 字节'], ['SYN-ACK 的头', 40, '40 字节'], ['之后每个包的头', 32, '32 字节'], ['固定部分', 20, '20 字节']], 44, mark=[0, 1], done=[2, 3]), kv=KV([['序号', '每个字节一个序号;SYN、FIN 各占 1 个'], ['确认号', '期望收到的下一个序号'], ['数据偏移', '头长 ÷ 4(SYN 为 11 → 44 字节)'], ['窗口', '16 位,配合缩放选项']], ['确认号'])),
    step("选项:SYN 的选项 24 字节 02 04 05 b4 01 03 03 06 01 01 08 0a … 04 02 00 00,逐个解码:MSS(类型 2,长度 4)= 1460;NOP(1 字节,用来对齐);窗口缩放(类型 3,长度 3)移位 6,即窗口字段要乘以 2^6;NOP NOP;时间戳(类型 8,长度 10)TSval 是本机的时间戳、TSecr = 0;SACK-permitted(类型 4,长度 2);EOL(类型 0,补齐到 4 字节的整数倍)。SYN-ACK 的选项 20 字节:MSS、SACK-permitted、时间戳、NOP、窗口缩放。之后带数据的包头长 32 字节,选项只剩 NOP NOP + 时间戳(12 字节)。12 个包里头长分布:44 字节 1 个、40 字节 1 个、32 字节 10 个。", t=tl(S(2)), mark=lidx(S(2), 'SYN 的选项 24 字节', 'MSS(类型 2', '窗口缩放', 'Timestamps(类型 8'), done=lidx(S(2), 'NOP(1 字节', 'SACK-permitted(类型 4', 'EOL', 'SYN-ACK 的选项', '带数据的包头长', '各种包的头长'), kv=KV([['MSS', '1460 = 1500 − 20 − 20'], ['窗口缩放', '移位 6:窗口 × 64'], ['时间戳', '8 字节,每个包 +12 字节(含 NOP NOP)'], ['SACK-permitted', '2 字节:允许选择性确认'], ['NOP / EOL', '对齐与结束']], ['窗口缩放'])),
    step("标志位组合:在 lo0 上下载 1 MiB(1048576 字节),共 98 个 TCP 包,标志组合:纯 ACK 92 个、ACK+PSH 2 个、SYN 1 个、ACK+SYN 1 个、ACK+PSH+FIN 1 个、ACK+FIN 1 个——整个连接里只有握手包没有 ACK 位,之后每个包都带 ACK。窗口字段(16 位原始值):客户端 SYN 是 65535(SYN 里的窗口不缩放),之后客户端的 ACK 里窗口字段最小 4085、最大 26523(要乘以 2^6 才是真实窗口)。服务端发出的数据包载荷最大 16332 字节 = MSS 16344 − 时间戳选项 12 字节;PSH 位出现 3 次——PSH 只是提示接收方尽快把数据交给应用,不改变传输。", t=tl(S(3)), mark=lidx(S(3), '窗口字段(16 位原始值)', '服务端发出的数据包'), done=lidx(S(3), '下载 1048576 字节'), b=bars([['纯 ACK', 92, '92'], ['ACK+PSH', 2, '2'], ['SYN / SYN+ACK', 2, '2'], ['FIN 相关', 2, '2']], 92, mark=[0], done=[1, 2, 3]), kv=KV([['98 个包', '92 个纯 ACK(94%)'], ['SYN', '窗口字段不缩放'], ['数据包载荷最大', '16332 = 16344 − 12(时间戳)'], ['PSH', '3 次,只是提示']], ['数据包载荷最大'])),
    step("紧急指针与 URG:用 send(…, MSG_OOB) 发 1 个“带外”字节。线上客户端发了三个包:普通数据 abc(ACK+PSH,3 字节,紧急指针 0)、1 字节的紧急数据(URG+ACK+PSH,紧急指针字段 1)、普通数据 def(ACK+PSH,3 字节,紧急指针 0)。接收方 recv(MSG_OOB) 拿到 b'!',普通 recv 拿到 b'abc'。URG 置位时,紧急指针指向紧急数据的位置(相对本包序号的偏移),这里是 1。它几乎没有被实际用过,而且“带外数据”在各系统里语义不一致,RFC 6093 建议新应用不要使用。", t=tl(S(4)), mark=lidx(S(4), 'URG+ACK+PSH'), done=lidx(S(4), '接收方 recv(MSG_OOB)', 'URG 标志置位时', '客户端发出:标志 ACK+PSH,载荷 3 字节,紧急指针字段 0'), kv=KV([['MSG_OOB 发出的包', 'URG+ACK+PSH,紧急指针 1'], ['接收方', 'recv(MSG_OOB) 取到 b\'!\''], ['建议', 'RFC 6093:新应用不要用']], ['建议'])),
]
A = mkartw('w37', 37, '网络协议,TCP,TCP头部,序号,确认号,标志位,选项,窗口缩放,URG,真实验证,动画演示',
    '逐字节解码真实 TCP 连接:SYN 头 44 字节(MSS 1460、窗口缩放 6、时间戳、SACK-permitted),相对序号与确认号逐包对应,数据包头 32 字节;lo0 下载 1 MiB 的 98 个包里 92 个纯 ACK;MSG_OOB 发出的 URG 包紧急指针为 1。',
    'TCP 头里每个字段到底在干什么?序号、确认号怎么对应?SYN 里那串选项各是什么?这篇在 en0 上抓一次真实的 HTTP 连接,逐个包逐字段解码,再用 lo0 看标志位的分布和已经被淘汰的 URG。',
    [('44 字节', '真实 SYN 的 TCP 头长度:20 字节固定 + 24 字节选项(MSS、窗口缩放、时间戳、SACK-permitted)'), ('92 / 98', 'lo0 上下载 1 MiB 时纯 ACK 包占的个数;只有握手的 SYN 没有 ACK 位'), ('16332 = 16344 − 12', '数据包的最大载荷:MSS 减去每个包都带的 12 字节时间戳选项')],
    [('固定头', '<p>源端口、目的端口、序号、确认号、数据偏移、标志、窗口、校验和、紧急指针,共 20 字节。SYN 和 FIN 各占一个序号,所以 ACK 的确认号比对方的序号多 1。</p>'),
     ('选项', '<p>SYN 里一次性协商 MSS、窗口缩放、时间戳、SACK-permitted;之后每个包只保留时间戳(12 字节)。数据偏移字段告诉接收方头有多长。</p>'),
     ('标志位', '<p>握手之后每个包都带 ACK;PSH 只是提示;FIN 与 RST 结束连接。lo0 下载 1 MiB 的 98 个包里 92 个是纯 ACK。</p>'),
     ('URG', '<p>紧急指针指向紧急数据的位置,MSG_OOB 发出的包能看到。语义不统一,不建议使用。</p>')],
    steps,
    [ENV_W + '。第一、二节是 en0 上 example.com 的一次真实 HTTP 请求(序号用相对值,端口用 C 表示本机的临时端口);第三、四节在 lo0 上做;窗口字段的真实窗口要乘以缩放系数(本篇只展示原始字段)',
     '没有验证:URG 在不同系统上的语义差别;选项的更多种类(TFO、MPTCP、MD5 签名等);ECN 位(CWR / ECE)的实际工作(本机 SYN 带 CWR+ECE 是协商 ECN);窗口缩放对服务器方向(窗口字段 16)的换算(服务器的缩放系数没有读)'],
    'TCP 头部')
